std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_);
    std::vector<std::size_t> indices(rows_);
    std::iota(indices.begin(), indices.end(), std::size_t{0});
    std::transform(indices.begin(), indices.end(), result.begin(),
                   [this](std::size_t r) {
                       return std::accumulate(indices.begin(), indices.end(),
                                              0.0,
                                              [this, r](double acc, std::size_t c) {
                                                  return acc + at(r, c);
                                              });
                   });
    return result;
}

